  p.vel.x += turbX * uniforms.dt * 30.0;
  p.vel.y += turbY * uniforms.dt * 30.0;

  // Drag
  p.vel *= uniforms.drag;

  // Integrate position
  p.pos += p.vel * uniforms.dt;

  // Boundary bounce (soft)
  if (p.pos.x < 0.0) { p.pos.x = 0.0; p.vel.x *= -0.5; }
